    },
    brand() {
      return this as any;
    },
    register(reg: any, meta: any): any {
      reg.add(this, meta);
      return this;
    },
    apply(fn: any, ...args: any[]) {
      return args.length === 0 ? fn(this) : fn(this, ...args);
