    SH: Fn(S) -> IV + 'static + Clone + Send,
    S: Clone + Send + Sync + 'static,
    IV: IntoView + 'static,
{
    type Response = Response<Body>;
    type Error = Infallible;
    type Future = Pin<
        Box<
            dyn Future<Output = Result<Response<Body>, Infallible>>
                + Send
                + 'static,
        >,
    >;

